"use strict";
// A registry of plugins: each is a function the program imports from its
// own module of this package and hands back here.
const plugins = new Map();
const api = {
  upper(s) {
    return s.toUpperCase();
  },
};
function register(name, plugin) {
  if (typeof plugin !== "function") throw new TypeError("plugin '" + name + "' is not a function");
  plugins.set(name, plugin(api));
}
function run(name, input) {
  const plugin = plugins.get(name);
  return plugin === undefined ? "?" : plugin.name + ":" + plugin.apply(input);
}
module.exports = { register, run };
